19	namespace att {
20	namespace {
21	// Tiling 调度配置相关常量
22	constexpr double kDefaultUbThreshold = 0.1;      // 默认 UB 阈值
23	constexpr uint32_t kDefaultCacheLineSize = 128;  // 默认CacheLine大小（字节）
24	
25	const uint32_t kUBAlignValue = 32u;
26	const uint32_t kConcatOuterDimAlign = 16u;
27	template <typename T>
28	af::Status UpdateLastTileAxisPromptAlign(const SubAxis *sub_axis, const AttAxis &arg_info, T &size) {
29	  GELOGD("[DFX] UpdateLastTileAxisPromptAlign sub_axis=[%s], is_node_innerest_dim=%d, bind_multicore=%d, axis_pos=%d",
30	         sub_axis->ToString().c_str(), arg_info.is_node_innerest_dim, arg_info.bind_multicore,
31	         static_cast<int>(arg_info.axis_pos));
32	  if (arg_info.is_node_innerest_dim && (!arg_info.bind_multicore) && (arg_info.axis_pos == AxisPosition::INNER)) {
33	    auto block_len = std::gcd(sub_axis->data_type_size, kUBAlignValue);
34	    GE_ASSERT_TRUE(block_len != 0, "block_len is 0");
35	    size.prompt_align = kUBAlignValue / block_len;
36	    GELOGD("[DFX] Set axis[%s] prompt_align to %u (kUBAlignValue=%u / block_len=%u), data_type_size=%u",
37	           arg_info.name.c_str(), size.prompt_align, kUBAlignValue, block_len, sub_axis->data_type_size);
38	  }
39	  return af::SUCCESS;
40	}
41	}  // namespace
42	af::Status GenerateTilingExpr::GetBufConstraint(std::map<HardwareDef, Expr> &hardware_cons,
43	                                                std::map<std::string, Expr> &container_exprs) {
44	  std::unordered_map<HardwareDef, Expr> buffer_occupy;
45	  BufOccupEvaluatorExprPtr buf_evaluator = af::MakeShared<BufOccupyExpr>(tuning_space_);
46	  GE_ASSERT_NOTNULL(buf_evaluator, "Create buff evaluator expr failed.");
47	  GE_ASSERT_SUCCESS(buf_evaluator->GetTotalBufferOccup(buffer_occupy, container_exprs),
48	                    "Collect buf constraints failed.");
49	  for (const auto &buff : buffer_occupy) {
50	    hardware_cons[buff.first] = buff.second;
51	    GELOGD("[DFX]Add buf constraint: %d = %s", buff.first, buff.second.Serialize().get());
52	  }
53	  return af::SUCCESS;
54	}
55	
56	af::Status GenerateTilingExpr::GetReservedUbSize(Expr &reserved_ub_size) {
57	  for (const auto &reserved_ub : tuning_space_->reserve_ub) {
58	    reserved_ub_size = reserved_ub_size + CreateExpr(reserved_ub.second);
59	  }
60	  return af::SUCCESS;
61	}
62	
63	af::Status GenerateTilingExpr::GetWorkSpaceSize(std::map<int64_t, Expr> &workspace_size_map) {
64	  workspace_size_map = tuning_space_->workspace_size_map;
65	  return af::SUCCESS;
66	}
67	
68	af::Status GenerateTilingExpr::GetPipePerformance(std::map<PipeType, Expr> &pipe_perf_object,
69	                                                  std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
70	                                                  std::vector<PerfBreakdownGroup> &perf_breakdowns, Expr &head_cost) {
71	  PipePerfExpr pipe_perf(tuning_space_);
72	  GE_ASSERT_SUCCESS(pipe_perf.GetPerfExpr(pipe_perf_object, ternary_ops, perf_breakdowns, head_cost),
73	                    "Get tiling performance failed.");
74	  return af::SUCCESS;
75	}
76	
77	af::Status GenerateTilingExpr::GetCoreConstraint(std::map<HardwareDef, Expr> &hardware_cons) {
78	  Expr block_dim_max_expr = CreateExpr(0U);
79	  // 所有block dim取最大值
80	  for (auto &core_info : tuning_space_->block_dims) {
81	    Expr block_dim_expr = CreateExpr(1U);
82	    for (auto &block_axis : core_info) {
83	      auto axis_size = ArgListManager::GetInstance().GetArgExpr(block_axis->name);
84	      if (!IsValid(axis_size)) {
85	        axis_size = block_axis->repeat;
86	        ArgListManager::GetInstance().SetArgExpr(block_axis->name, axis_size);
87	      }
88	      block_dim_expr = af::sym::Mul(block_dim_expr, axis_size);
89	    }
90	    block_dim_max_expr = af::sym::Max(block_dim_expr, block_dim_max_expr);
91	  }
92	  hardware_cons[HardwareDef::CORENUM] = block_dim_max_expr;
93	  GELOGD("[DFX]Add core constraint: %d = %s", HardwareDef::CORENUM, block_dim_max_expr.Serialize().get());
94	  return af::SUCCESS;
95	}
96	
97	af::Status GenerateTilingExpr::MakeArg(const SubAxis *sub_axis,
98	                                       std::map<const SubAxis *, std::set<HardwareDef>> related_scopes,
99	                                       AttAxisPtr &arg_info) const {
100	  InitArgInfo(sub_axis, arg_info);
101	  if (sub_axis->repeat.IsConstExpr()) {
102	    GE_ASSERT_GRAPH_SUCCESS(MakeConstArg(sub_axis, arg_info));
103	  } else {
104	    GE_ASSERT_GRAPH_SUCCESS(MakeVarArg(sub_axis, related_scopes, arg_info));
105	  }
106	  return af::SUCCESS;
107	}
108	
109	void GenerateTilingExpr::InitArgInfo(const SubAxis *sub_axis, AttAxisPtr &arg_info) const {
110	  arg_info->name = sub_axis->name;
111	  arg_info->axis_pos = sub_axis->axis_type;
112	  arg_info->is_node_innerest_dim = sub_axis->is_node_innerest_dim;
113	  arg_info->bind_multicore = sub_axis->is_bind_multi_core;
114	  arg_info->is_last = sub_axis->is_last;
115	  arg_info->is_concat_outer_dim = sub_axis->is_concat_vec_axis && !sub_axis->is_node_innerest_dim;
116	  arg_info->is_concat_inner_dim = sub_axis->is_concat_vec_axis && sub_axis->is_node_innerest_dim;
117	  arg_info->is_reduce_split_axis = sub_axis->is_reduce_split_axis;
118	  arg_info->is_broadcast_split_axis = sub_axis->is_broadcast_split_axis;
119	}
120	
121	af::Status GenerateTilingExpr::MakeConstArg(const SubAxis *sub_axis, AttAxisPtr &arg_info) const {
122	  auto size = af::MakeShared<SymConstInfo>(sub_axis->repeat);
123	  GE_ASSERT_NOTNULL(size, "Create sym const info failed.");
124	  std::vector<std::pair<Expr, Expr>> vars_value;
125	  double const_value = 0;
126	  auto ret = sub_axis->repeat.GetResult(vars_value, const_value);
127	  GE_ASSERT_GRAPH_SUCCESS(ret, "Get const expr value failed, ret [%d].", ret);
128	  size->const_value = static_cast<uint32_t>(const_value);
129	  size->value_range = sub_axis->value_range;
130	  size->data_type_size = sub_axis->data_type_size;
131	  GE_ASSERT_TRUE(sub_axis->data_type_size != 0, "sub_axis->data_type_size is 0");
132	  GELOGD("[DFX] MakeArg (const) axis[%s]: is_concat_inner_dim=%d, is_concat_outer_dim=%d, data_type_size=%u",
133	         sub_axis->name.c_str(), arg_info->is_concat_inner_dim, arg_info->is_concat_outer_dim,
134	         sub_axis->data_type_size);
135	  GE_ASSERT_GRAPH_SUCCESS(UpdateLastTileAxisPromptAlign(sub_axis, *arg_info, *size));
136	  if (arg_info->is_concat_inner_dim) {
137	    size->prompt_align = kUBAlignValue / sub_axis->data_type_size;
138	  }
139	  arg_info->size = size;
140	  return af::SUCCESS;
141	}
142	
143	af::Status GenerateTilingExpr::MakeVarArg(const SubAxis *sub_axis,
144	                                          std::map<const SubAxis *, std::set<HardwareDef>> &related_scopes,
145	                                          AttAxisPtr &arg_info) const {
146	  Expr expr = ArgListManager::GetInstance().GetArgExpr(sub_axis->name);
147	  auto size = af::MakeShared<SymVarInfo>(expr);
148	  GE_ASSERT_NOTNULL(size, "Create sym var info failed.");
149	  size->align = sub_axis->align;
150	  size->value_range = sub_axis->value_range;
151	  size->data_type_size = sub_axis->data_type_size;
152	  GE_ASSERT_TRUE(sub_axis->data_type_size != 0, "sub_axis->data_type_size is 0");
153	  GELOGD(
154	      "[DFX] MakeArg (non-const) axis[%s]: is_concat_inner_dim=%d, is_concat_outer_dim=%d, data_type_size=%u, "
155	      "axis_pos=%d",
156	      sub_axis->name.c_str(), arg_info->is_concat_inner_dim, arg_info->is_concat_outer_dim, sub_axis->data_type_size,
157	      static_cast<int>(arg_info->axis_pos));
158	  if (arg_info->is_concat_inner_dim) {
159	    size->prompt_align = kUBAlignValue / sub_axis->data_type_size;
160	  } else if (arg_info->is_concat_outer_dim) {
161	    size->prompt_align = kConcatOuterDimAlign;
162	  }
163	  UpdateLastTileAxisPromptAlign(sub_axis, *arg_info, *size);
164	  if (related_scopes.find(sub_axis) != related_scopes.end()) {
165	    for (auto &scope : related_scopes[sub_axis]) {
166	      size->related_scope.emplace_back(scope);
167	    }
168	  }
169	  arg_info->size = size;
170	  return af::SUCCESS;
171	}
172	
173	af::Status GenerateTilingExpr::GetSubAxisArgs(std::vector<AttAxisPtr> &arg_lists) {
174	  std::map<SubAxis *, AttAxisPtr> relation;
175	  for (const auto &sub_axis : tuning_space_->sub_axes) {
176	    auto arg_info = af::MakeShared<AttAxis>();
177	    GE_ASSERT_NOTNULL(arg_info, "Create att axis failed.");
178	    GE_ASSERT_SUCCESS(MakeArg(sub_axis.get(), tuning_space_->related_scopes, arg_info), "Make arg info failed.");
179	    relation[sub_axis.get()] = arg_info;
180	    arg_lists.emplace_back(arg_info);
181	  }
182	  // 构造轴依赖关系
183	  for (const auto &iter : relation) {
184	    for (auto axis : iter.first->orig_axis) {
185	      auto att = relation.find(axis);
186	      if (att != relation.end()) {
187	        iter.second->orig_axis.emplace_back(att->second.get());
188	      }
189	    }
190	    for (auto axis : iter.first->parent_axis) {
191	      auto att = relation.find(axis);
192	      if (att != relation.end()) {
193	        iter.second->from_axis.emplace_back(att->second.get());
194	      }
195	    }
196	  }
197	
198	  return af::SUCCESS;
199	}
200	
201	af::Status GenerateTilingExpr::GetAxisConstraints(std::map<std::string, std::vector<std::pair<Expr, Expr>>> &eq_exprs,
202	                                                  std::map<std::string, std::vector<Expr>> &leq_exprs) {
203	  for (const auto &cur_axis : tuning_space_->sub_axes) {
204	    GE_ASSERT_NOTNULL(cur_axis, "Get cur_axis failed.");
205	    if ((cur_axis->axis_type != AxisPosition::OUTER) && (!cur_axis->parent_axis.empty())) {
206	      Expr father_size = CreateExpr(1U);
207	      for (auto &father : cur_axis->parent_axis) {
208	        father_size = af::sym::Mul(father_size, ArgListManager::GetInstance().GetArgExpr(father->name));
209	      }
210	      auto size = cur_axis->repeat;
211	      if (cur_axis->enable_tail == false) {
212	        eq_exprs[kFatherToChildNoTail].emplace_back(std::make_pair(father_size, size));
213	      } else if (cur_axis->enable_pad == true) {
214	        // 目前不需要
215	        continue;
216	      } else {
217	        leq_exprs[kFatherToChildLarger].emplace_back(af::sym::Sub(size, father_size));
218	      }
219	    }
220	  }
221	  return af::SUCCESS;
222	}
223	
224	void GenerateTilingExpr::GetOutputSize(uint32_t &output_size) {
225	  uint32_t tmp_output_size = 0;
226	  for (const auto &node : tuning_space_->node_infos) {
227	    if (node.node_type == "Output") {
228	      tmp_output_size++;
229	    }
230	  }
231	  output_size = tmp_output_size;
232	}
