234	af::Status GenerateTilingExpr::GetTensorExpr(std::map<std::string, Expr> &tensor_exprs) {
235	  for (const auto &node : tuning_space_->node_infos) {
236	    for (const auto &input : node.inputs) {
237	      GE_ASSERT_NOTNULL(input, "Get input failed.");
238	      Expr tensor_size_expr = ArgListManager::GetInstance().GetArgExpr(input->name);
239	      if (IsValid(tensor_size_expr)) {
240	        tensor_exprs[input->name] = tensor_size_expr;
241	      }
242	    }
243	    for (const auto &output : node.outputs) {
244	      GE_ASSERT_NOTNULL(output, "Get output failed.");
