254	bool NeedUBMCTradeoff(TensorPtr tensor) {
255	  // 不是GM的不纳入ub mc tradeoff
256	  if (tensor->loc != HardwareDef::GM) {
257	    return false;
258	  }
259	  auto &repeats = tensor->repeat;
260	  auto &strides = tensor->gm_stride;
261	  GELOGD("tensor [%s] : repeats[%s], strides[%s]", tensor->name.c_str(), tensor->GetRepeat().c_str(),
262	         tensor->GetStride().c_str());
263	  if (repeats.size() <= 1) {
264	    return false;
265	  }
266	  if (repeats.size() == strides.size()) {
267	    Expr last_stride = af::sym::kSymbolOne;
268	    for (int32_t i = strides.size() - 2; i >= 0; i--) {
269	      if (strides[i + 1] != af::sym::kSymbolZero) {
270	        last_stride = strides[i + 1];
271	      }
272	      if (strides[i] == af::sym::kSymbolZero) {
273	        continue;
274	      }
275	      auto expect_stride = repeats[i + 1] * last_stride;
276	      if (strides[i] != expect_stride) {
277	        return true;
278	      }
279	    }
280	  }
281	  return false;
282	}
