284	void GenerateTilingExpr::UpdateNeedUBMCTradeoff(ModelInfo &model_info) {
285	  for (auto &node_info : tuning_space_->node_infos) {
286	    const bool need_tradeoff_by_output =
287	        std::any_of(node_info.outputs.begin(), node_info.outputs.end(),
288	                    [](auto &output_tensor) { return NeedUBMCTradeoff(output_tensor); });
289	    const bool need_tradeoff_by_input = std::any_of(node_info.inputs.begin(), node_info.inputs.end(),
290	                                                    [](auto &input_tensor) { return NeedUBMCTradeoff(input_tensor); });
291	    if (need_tradeoff_by_output || need_tradeoff_by_input) {
292	      GELOGI(
293	          "model [%s] case [%d] need ub mc tradeoff, output tensor need tradeoff: %d, input tensor need tradeoff: %d",
294	          model_info.schedule_group_ident.GetGroupPrefixSnakeCase().c_str(), model_info.tiling_case_id,
295	          need_tradeoff_by_output, need_tradeoff_by_input);
296	      model_info.tiling_schedule_config.trade_off_config.is_enable = true;
297	      return;
298	    }
299	  }
300	}
