302	// 判断是否应该跳过某个轴
303	bool GenerateTilingExpr::ShouldSkipAxis(const SubAxis *sub_axis,
304	                                        const std::set<std::string> &reduce_split_axis_names) const {
305	  // 跳过Reduce分核轴和Broadcast分核轴
306	  if (sub_axis->is_reduce_split_axis || sub_axis->is_broadcast_split_axis) {
307	    GELOGD("[DFX] ShouldSkipAxis: skip sub_axis [%s] (is_reduce_split or is_broadcast_split)", sub_axis->name.c_str());
308	    return true;
309	  }
310	  // 检查是否来自Reduce分核轴
311	  if (IsFromReduceSplit(sub_axis, reduce_split_axis_names)) {
312	    GELOGD("[DFX] ShouldSkipAxis: skip sub_axis [%s] as it's from reduce split", sub_axis->name.c_str());
313	    return true;
314	  }
315	  return false;
316	}
317	
318	// 检查轴是否来自Reduce分核轴（通过orig_axis链检查）
319	bool GenerateTilingExpr::IsFromReduceSplit(const SubAxis *sub_axis,
320	                                           const std::set<std::string> &reduce_split_axis_names) const {
321	  std::set<const SubAxis *> visited;
322	  std::vector<const SubAxis *> to_check = {sub_axis};
323	
324	  while (!to_check.empty()) {
325	    const SubAxis *current = to_check.back();
326	    to_check.pop_back();
327	
328	    if (!visited.insert(current).second) {
329	      continue;
330	    }
331	
332	    // 检查当前轴是否是Reduce分核轴的子轴
333	    for (const auto *orig_axis : current->orig_axis) {
334	      if (orig_axis == nullptr) {
335	        continue;
336	      }
337	      if (reduce_split_axis_names.find(orig_axis->name) != reduce_split_axis_names.end()) {
338	        GELOGD("[DFX] IsFromReduceSplit: sub_axis [%s] is from reduce split (orig_axis [%s])", sub_axis->name.c_str(),
339	               orig_axis->name.c_str());
340	        return true;
341	      }
342	      to_check.push_back(orig_axis);
343	    }
344	  }
345	  return false;
346	}
