348	// 查找A轴：Vectorized轴里从右向左数所有非R轴
349	// 只从 Store 节点的 loop_axes (SubAxis) 中查找
350	std::vector<const AttAxis *> GenerateTilingExpr::FindAAxis(const std::vector<AttAxisPtr> &arg_list) const {
351	  std::vector<const AttAxis *> result;
352	
353	  // 收集 Reduce 分核轴名称
354	  std::set<std::string> reduce_split_axis_names = CollectReduceSplitAxisNames();
355	
356	  GELOGD("[DFX] FindAAxis: reduce_split_axis_names=%s",
357	         std::accumulate(
358	             reduce_split_axis_names.begin(), reduce_split_axis_names.end(), std::string(),
359	             [](const std::string &acc, const std::string &name) { return acc.empty() ? name : acc + "," + name; })
360	             .c_str());
361	
362	  // 收集 Store 节点的 SubAxes
363	  std::vector<SubAxis *> all_sub_axes = CollectStoreSubAxes();
364	
365	  // 从右向左遍历（最内层开始）
366	  for (auto it = all_sub_axes.rbegin(); it != all_sub_axes.rend(); ++it) {
367	    const SubAxis *sub_axis = *it;
368	
369	    GELOGD("[DFX] FindAAxis: checking sub_axis [%s], is_reduce_split=%d, is_broadcast_split=%d", sub_axis->name.c_str(),
370	           sub_axis->is_reduce_split_axis, sub_axis->is_broadcast_split_axis);
371	
372	    // 根据该轴是否被Reduce，判断是否应该跳过该轴
373	    if (ShouldSkipAxis(sub_axis, reduce_split_axis_names)) {
374	      continue;
375	    }
376	
377	    // 通过 name 匹配添加到 result
378	    AddAxisByName(sub_axis, arg_list, result);
379	  }
380	
381	  GELOGI("[DFX] FindAAxis: found %zu A axes[%s]", result.size(),
382	         std::accumulate(result.begin(), result.end(), std::string(), [](const std::string &acc, const AttAxis *axis) {
383	           return acc.empty() ? axis->name : acc + "," + axis->name;
384	         }).c_str());
385	  return result;
386	}
