388	// 收集 Reduce 分核轴名称
389	std::set<std::string> GenerateTilingExpr::CollectReduceSplitAxisNames() const {
390	  std::set<std::string> reduce_split_axis_names;
391	  for (const auto &node : tuning_space_->node_infos) {
392	    AttUtils::CollectReduceAxisNames(node, reduce_split_axis_names);
393	  }
394	  return reduce_split_axis_names;
395	}
