397	// 收集 Store 节点的 SubAxes
398	std::vector<SubAxis *> GenerateTilingExpr::CollectStoreSubAxes() const {
399	  std::vector<SubAxis *> all_sub_axes;
400	  for (const auto &node : tuning_space_->node_infos) {
401	    bool is_store = (node.node_type == kStore);
402	    if (node.node_ptr != nullptr) {
403	      is_store = AttUtils::IsStoreNode(node.node_ptr.get());
404	    }
405	
406	    if (!is_store) {
407	      continue;
408	    }
409	
410	    GELOGD("[DFX] CollectStoreSubAxes: node_name=%s, node_type=%s, inputs=%s", node.name.c_str(),
411	           node.node_type.c_str(),
412	           std::accumulate(node.inputs.begin(), node.inputs.end(), std::string(),
413	                           [](const std::string &acc, const auto &input) {
414	                             return acc.empty() ? input->ToString() : acc + "," + input->ToString();
415	                           })
416	               .c_str());
417	
418	    for (const auto &input : node.inputs) {
419	      all_sub_axes.insert(all_sub_axes.cend(), input->dim_info.begin(), input->dim_info.end());
420	    }
421	    // 当前仅考虑一个输出节点，后续扩展时需处理多个输出节点
422	    break;
423	  }
424	  return all_sub_axes;
425	}
