427	// 通过名称匹配添加 A 轴
428	void GenerateTilingExpr::AddAxisByName(const SubAxis *sub_axis, const std::vector<AttAxisPtr> &arg_list,
429	                                       std::vector<const AttAxis *> &result) const {
430	  for (const auto &axis : arg_list) {
431	    if (axis->name == sub_axis->name) {
432	      result.push_back(axis.get());
433	      GELOGD("[DFX] AddAxisByName: found A axis [%s]", sub_axis->name.c_str());
434	      break;
435	    }
436	  }
437	}
