439	// 应用符号转换（通用函数）
440	Expr GenerateTilingExpr::ApplySymbolTransform(const Expr &size_expr, const SymbolTransformFunc &transform_func) const {
441	  auto symbols = size_expr.FreeSymbols();
442	  std::vector<std::pair<Expr, Expr>> replace_pairs;
443	
444	  for (const auto &sym : symbols) {
445	    if (sym.IsConstExpr()) {
446	      continue;
447	    }
448	    std::string sym_name = Str(sym);
449	    std::string transformed_expr = transform_func(sym_name);
450	    replace_pairs.emplace_back(sym, af::Symbol(transformed_expr.c_str()));
451	  }
452	
453	  return size_expr.Replace(replace_pairs);
454	}
