463	// 将原始轴转换为 axis.value 形式
464	Expr GenerateTilingExpr::ApplyOriginalAxisTransform(const Expr &size_expr) const {
465	  return ApplySymbolTransform(size_expr, [](const std::string &sym_name) { return sym_name + ".value"; });
466	}
