476	// 计算惩罚的core_num_ratio
477	Expr GenerateTilingExpr::CalcPenaltyCoreNumRatio(const AttAxis *split_axis,
478	                                                 const std::vector<const AttAxis *> &a_axes) const {
479	  if (split_axis == nullptr || a_axes.empty()) {
480	    return af::Symbol(1);
481	  }
482	
483	  GELOGI("[DFX] CalcPenaltyCoreNumRatio: split_axis=%s, a_axes_count=%zu", split_axis->name.c_str(), a_axes.size());
484	
485	  // 计算所有A轴的size乘积，Tile切分轴替换为 upper_bound 形式
486	  Expr a_axis_size = af::Symbol(1);
487	  uint32_t data_type_size = split_axis->size->data_type_size;
488	
489	  for (const AttAxis *a_axis : a_axes) {
490	    if (a_axis->size == nullptr || !a_axis->size->symbol_expr.IsValid()) {
491	      continue;
492	    }
493	
494	    // 获取轴大小表达式
495	    Expr size_expr = a_axis->size->symbol_expr;
496	    Expr final_size = size_expr;
497	
498	    // 只有Tile切分轴(INNER)才替换为 upper_bound 形式
499	    if (a_axis->axis_pos == AxisPosition::INNER) {
500	      final_size = ApplyUpperBoundTransform(size_expr);
501	      GELOGD("[DFX] CalcPenaltyCoreNumRatio: a_axis=%s (INNER, Tile), size=%s -> upper_bound=%s", a_axis->name.c_str(),
502	             Str(size_expr).c_str(), Str(final_size).c_str());
503	    } else if (a_axis->axis_pos == AxisPosition::ORIGIN) {
504	      final_size = ApplyOriginalAxisTransform(size_expr);
505	      GELOGD("[DFX] CalcPenaltyCoreNumRatio: a_axis=%s (ORIGIN, Tile), size=%s -> size_value=%s", a_axis->name.c_str(),
506	             Str(size_expr).c_str(), Str(final_size).c_str());
507	    } else {
508	      GELOGD("[DFX] CalcPenaltyCoreNumRatio: a_axis=%s (%s), size=%s (no upper_bound)", a_axis->name.c_str(),
509	             a_axis->axis_pos == AxisPosition::OUTER ? "OUTER" : "MERGED", Str(size_expr).c_str());
510	    }
511	
512	    a_axis_size = a_axis_size * final_size;
513	
514	    // 获取数据类型大小
515	    if (a_axis->size->data_type_size > 0) {
516	      data_type_size = a_axis->size->data_type_size;
517	    }
518	
519	    GELOGD("[DFX] CalcPenaltyCoreNumRatio: accumulated=%s", Str(a_axis_size).c_str());
520	  }
521	
522	  // 获取惩罚计算使用的CacheLine大小；特殊融合场景可使用独立粒度，不影响物理Cache Line配置。
523	  uint32_t cache_line_size =
524	      tuning_space_->penalty_cache_line_size > 0 ? tuning_space_->penalty_cache_line_size : GetCacheLineSize();
525	
526	  // 计算 core_num_ratio = (a_axis_size * data_type_size) / cache_line_size
527	  Expr core_num_ratio = (a_axis_size * af::Symbol(data_type_size)) / af::Symbol(cache_line_size);
528	
529	  GELOGI(
530	      "[DFX] Calculated penalty core_num_ratio: split_axis=%s, a_axes_count=%zu, "
531	      "total_a_size=%s, data_type_size=%u, cache_line_size=%u, ratio=%s",
532	      split_axis->name.c_str(), a_axes.size(), Str(a_axis_size).c_str(), data_type_size, cache_line_size,
533	      Str(core_num_ratio).c_str());
534	
535	  return core_num_ratio;
536	}
537	
538	// 应用惩罚配置到 ModelInfo
539	void GenerateTilingExpr::ApplyPenaltyConfigToModelInfo(ModelInfo &model_info) {
540	  // 0. 首先从 TilingScheduleConfigTable 获取基础配置（无论是否有惩罚场景）
541	  if (tuning_space_->tiling_schedule_config_table != nullptr) {
542	    model_info.tiling_schedule_config = tuning_space_->tiling_schedule_config_table->GetModelTilingScheduleConfig();
543	    GELOGI("[DFX] Loaded base TilingScheduleConfig from table, tiling_schedule_config=%s, model_name=%s",
544	           model_info.tiling_schedule_config.DebugString().c_str(), model_info.graph_name.c_str());
545	  } else {
546	    GELOGD("[DFX] tiling_schedule_config_table is null, using default TilingScheduleConfig, model_name=%s",
547	           model_info.graph_name.c_str());
548	  }
549	
550	  // 1. 检查配置是否启用Reduce分核惩罚功能（通过TilingScheduleConfigTable接口）
551	  if (tuning_space_->tiling_schedule_config_table == nullptr) {
552	    GELOGD("[DFX] tiling_schedule_config_table is null, skip penalty calculation, model_name=%s",
553	           model_info.graph_name.c_str());
554	    return;
555	  }
556	
557	  bool enable_penalty = tuning_space_->tiling_schedule_config_table->IsCoreNumThresholdPenaltyEnable();
558	  GELOGI("[DFX] Reduce split penalty config: enabled=%s (from TilingScheduleConfigTable), model_name=%s",
559	         enable_penalty ? "true" : "false", model_info.graph_name.c_str());
560	
561	  if (!enable_penalty) {
562	    GELOGD("[DFX] Reduce split penalty is disabled by config, skip penalty calculation, model_name=%s",
563	           model_info.graph_name.c_str());
564	    return;
565	  }
566	
567	  // 2. 检查是否存在Reduce分核Store冲突（暂时不考虑Broadcast分核场景）
568	  for (const auto &axis : model_info.arg_list) {
569	    if (axis->is_reduce_split_axis) {
570	      // 先查找所有A轴
571	      std::vector<const AttAxis *> a_axes = FindAAxis(model_info.arg_list);
572	
573	      GELOGI("[DFX] Found %zu A axes for penalty calculation", a_axes.size());
574	
575	      // 计算惩罚 ratio
576	      Expr penalty_core_num_ratio = CalcPenaltyCoreNumRatio(axis.get(), a_axes);
577	
578	      // 3. 设置惩罚配置（覆盖基础配置）
579	      model_info.tiling_schedule_config.trade_off_config.ub_ratio = af::Symbol(kDefaultUbThreshold);
580	      model_info.tiling_schedule_config.trade_off_config.core_num_ratio =
581	          af::sym::Min(penalty_core_num_ratio, af::Symbol(1.0));
582	      model_info.tiling_schedule_config.trade_off_config.is_enable = true;
583	      model_info.tiling_schedule_config.is_penalty_config = true;
584	
585	      GELOGI(
586	          "[DFX] Applied Reduce split Store penalty, model_name=%s, split_axis=%s, "
587	          "core_num_ratio=%s, ub_ratio=%f",
588	          model_info.graph_name.c_str(), axis->name.c_str(), Str(penalty_core_num_ratio).c_str(), kDefaultUbThreshold);
589	      return;
590	    }
591	  }
592	
593	  GELOGD("[DFX] No Reduce split axis found, model_name=%s", model_info.graph_name.c_str());
594	}
595	
596	af::Status GenerateTilingExpr::Generate(ModelInfo &model_info) {
597	  GE_ASSERT_SUCCESS(ArgListManager::GetInstance().LoadArgList(tuning_space_), "Get tuning args failed.");
598	  model_info.variable_expr_map = ArgListManager::GetInstance().GetVariableExprMap();
599	  model_info.variable_name_map = ArgListManager::GetInstance().GetVariableNameMap();
600	  GELOGD("Get tuning args success.");
601	
602	  GE_ASSERT_SUCCESS(GetBufConstraint(model_info.hardware_cons, model_info.container_exprs),
603	                    "Get buf constraints failed.");
604	  GELOGD("Get buf constraints success.");
605	
606	  GE_ASSERT_SUCCESS(GetCoreConstraint(model_info.hardware_cons), "Get core constraints failed.");
607	  GELOGD("Get core constraints success.");
608	
609	  GE_ASSERT_SUCCESS(GetReservedUbSize(model_info.reserved_ub_size), "Get reserved ub size failed.");
610	  GELOGD("Get reserved ub size success.");
611	
612	  GE_ASSERT_SUCCESS(GetPipePerformance(model_info.objects, model_info.ternary_op_map, model_info.perf_breakdowns,
613	                                       model_info.head_cost),
614	                    "Get perf objects failed.");
615	  model_info.tiling_schedule_config_table = tuning_space_->tiling_schedule_config_table;
616	
617	  GE_ASSERT_SUCCESS(GetWorkSpaceSize(model_info.workspace_size_map), "Get workspace size failed.");
618	
619	  GE_ASSERT_SUCCESS(GetSubAxisArgs(model_info.arg_list), "Get args list failed.");
620	
621	  GetAxisConstraints(model_info.eq_exprs, model_info.leq_exprs);
622	  GetOutputSize(model_info.output_size);
623	
624	  // 如果已经因为 Reduce 分核使能了 trade_off，则不需要再更新
625	  if (!model_info.enable_group_parallel && !model_info.tiling_schedule_config.is_penalty_config) {
626	    UpdateNeedUBMCTradeoff(model_info);
627	  }
628	
629	  // 检测并应用惩罚配置（根据是否存在Reduce分核场景，后续补齐Broadcast分核场景）
630	  ApplyPenaltyConfigToModelInfo(model_info);
631	
632	  return af::SUCCESS;
633	}
