88	af::Status CheckExecConditionBroadcast(const TuningSpacePtr tuning_space, const NodeInfo &node, SubAxis *axis,
89	                                       bool &is_split, Expr **fused_axis) {
90	  GE_ASSERT_NOTNULL(tuning_space);
91	  GE_ASSERT_NOTNULL(axis);
92	  GE_ASSERT_NOTNULL(fused_axis);
93	  if (node.exec_condition != af::ExecuteCondition::kCacheBlockSplitFusedBroadcastAxis &&
94	      node.exec_condition != af::ExecuteCondition::kCacheBlockSplitOriginBroadcastAxis) {
95	    GELOGD("exec_condition not match");
96	    return af::SUCCESS;
97	  }
98	  is_split = true;
99	  if (node.exec_condition == af::ExecuteCondition::kCacheBlockSplitFusedBroadcastAxis) {
100	    for (const auto &axes : tuning_space->sub_axes) {
101	      GE_ASSERT_NOTNULL(axes);
