103	        continue;
104	      }
105	      for (const auto parent_axis : axes->parent_axis) {
106	        GE_ASSERT_NOTNULL(parent_axis);
107	        if (parent_axis->name == axis->name) {
108	          GELOGD("fused_axis %s", Str(axes->repeat).c_str());
