128	void ExeTimePassManager::UpdateBufNode(const std::vector<NodeInfo> &nodes) {
129	  std::string log;
130	  bool broadcast_node = false;
131	  for (int32_t i = nodes.size() - 1; i >= 0; --i) {
132	    auto &node = nodes[i];
133	    if (node.exec_condition == af::ExecuteCondition::kCacheBlockSplitFusedBroadcastAxis ||
134	        node.exec_condition == af::ExecuteCondition::kCacheBlockSplitOriginBroadcastAxis) {
135	      GELOGD("insert brc inline node by exec_condition %s", node.name.c_str());
136	      brc_buf_node_.insert(node.name);
137	    }
138	    if (broadcast_node) {
139	      brc_buf_node_.insert(node.name);
140	    }
141	    if (node.node_type == kBroadcast) {
142	      brc_buf_node_.insert(node.name);
143	      broadcast_node = true;
144	    } else if (node.node_type == kLoad) {
145	      broadcast_node = false;
146	      const auto platform = optimize::PlatformFactory::GetInstance().GetPlatform();
147	      if (platform != nullptr && ascgen_utils::IsLinkToBrdcst(node.node_ptr, platform->BroadcastTypes())) {
148	        GELOGD("insert brc inline node %s", node.name.c_str());
149	        brc_buf_node_.insert(node.name);
150	      }
151	    }
152	  }
153	  for (const auto &node_name : brc_buf_node_) {
154	    log += node_name + ", ";
155	  }
