171	bool ExeTimePassManager::GetRLoop(const NodeInfo &node, Expr &r_loop) const {
172	  for (const auto &axis : node.loop_axes) {
173	    GE_ASSERT_NOTNULL(axis, "Get axis failed.");
174	    if (axis->axis_type != AxisPosition::OUTER && axis->axis_type != AxisPosition::INNER) {
175	      continue;
176	    }
177	    for (const auto &node_name : node.from_data) {
178	      bool r_split = false;
179	      for (const auto &orig_axis : axis->orig_axis) {
180	        CheckSplit(reduce_axis_, node_name, orig_axis->name, r_split);
181	      }
182	      if (r_split) {
183	        r_loop = axis->repeat;
184	        GELOGD("r_loop of [%s] is [%s].", node.name.c_str(), Str(r_loop).c_str());
185	        return true;
186	      }
187	    }
188	  }
189	  return false;
190	}
