192	/*
193	brc缓存执行逻辑：
194	1.递归计算节点的输入信息，将每一个节点与一个或多个Data节点绑定
195	2.扫描Broadcast节点与Reduce节点，根据绑定的Data节点确定每个Data节点的B轴，A轴与R轴
196	3.扫描Load至Broadcast间的所有节点
197	4.判断这些节点的循环轴间是否存在绑定的Data节点的B切分轴，若存在，则使能缓存：
198	1）若切分轴同时为R轴或非A轴，则使用性能公式除以切分轴的循环次数
199	2）若切分轴同时是A轴，且当前loop axis中与R轴相关的循环轴的循环轮次为1，则使用性能公式除以B切分轴的循环次数，否则不做压缩
200	*/
201	bool ExeTimePassManager::CheckAxisSplit(const NodeInfo &node, const SubAxis *axis, Expr *fused_axis) const {
202	  bool b_split = false;
203	  bool a_split = false;
204	  bool r_split = false;
205	  for (const auto &node_name : node.from_data) {
206	    for (const auto &orig_axis : axis->orig_axis) {
207	      CheckSplit(broadcast_axis_, node_name, orig_axis->name, b_split);
208	      CheckSplit(reduce_axis_, node_name, orig_axis->name, r_split);
209	      CheckSplit(non_reduce_axis_, node_name, orig_axis->name, a_split);
210	      CheckExecConditionBroadcast(tuning_space_, node, orig_axis, b_split, &fused_axis);
211	    }
212	    if (b_split) {
213	      return true;
214	    }
215	  }
216	  return b_split;
217	}
218	
219	TernaryOp ExeTimePassManager::HandleBroadcastSplit(const NodeInfo &node, const Expr &exe_time,
220	                                                   const Expr &fused_exe_time) const {
221	  GELOGD("[DFX] fused broadcast updates [%s] exe time : [%s] -> [%s]", node.name.c_str(), Str(exe_time).c_str(),
222	         Str(fused_exe_time).c_str());
223	  return TernaryOp(fused_exe_time);
224	}
225	
226	TernaryOp ExeTimePassManager::HandleReduceOrNormalSplit(const NodeInfo &node, const Expr &exe_time, const SubAxis *axis,
227	                                                        bool r_split, bool a_split) const {
228	  Expr cur_exe_time = af::sym::Div(exe_time, axis->repeat);
229	  if (r_split || !a_split) {
230	    GELOGD("Axis [%s] r_split and not asplit.", axis->name.c_str());
231	    GELOGD("Brc buf module updates [%s] exe time : [%s] -> [%s]", node.name.c_str(), Str(exe_time).c_str(),
232	           Str(cur_exe_time).c_str());
233	    return TernaryOp(cur_exe_time);
234	  }
235	  GELOGD("Axis [%s] a_split.", axis->name.c_str());
236	  Expr r_loop;
237	  if (GetRLoop(node, r_loop)) {
238	    GELOGD("Brc buf module updates [%s] exe time : [%s] -> [%s == 1 ? %s : %s]", node.name.c_str(),
239	           Str(exe_time).c_str(), Str(r_loop).c_str(), Str(cur_exe_time).c_str(), Str(exe_time).c_str());
240	    return TernaryOp(CondType::K_EQ, r_loop, CreateExpr(1.0f), af::sym::Div(cur_exe_time, r_loop), exe_time);
241	  }
242	  return TernaryOp(exe_time);
243	}
244	
245	TernaryOp ExeTimePassManager::UpdateNodeExeTime(const NodeInfo &node, const Expr &exe_time) const {
246	  if (brc_buf_node_.find(node.name) == brc_buf_node_.end()) {
247	    return TernaryOp(exe_time);
248	  }
249	  Expr *fused_axis = nullptr;
250	  bool b_split = false;
251	  bool a_split = false;
252	  bool r_split = false;
253	
254	  for (const auto &axis : node.loop_axes) {
255	    GE_ASSERT_NOTNULL(axis, "Get axis failed.");
256	    if (axis->axis_type != AxisPosition::OUTER && axis->axis_type != AxisPosition::INNER) {
257	      continue;
258	    }
259	    // Reset flags for each axis
260	    b_split = false;
261	    a_split = false;
262	    r_split = false;
263	
264	    for (const auto &node_name : node.from_data) {
265	      for (const auto &orig_axis : axis->orig_axis) {
266	        CheckSplit(broadcast_axis_, node_name, orig_axis->name, b_split);
267	        CheckSplit(reduce_axis_, node_name, orig_axis->name, r_split);
268	        CheckSplit(non_reduce_axis_, node_name, orig_axis->name, a_split);
269	        CheckExecConditionBroadcast(tuning_space_, node, orig_axis, b_split, &fused_axis);
270	      }
271	      if (b_split) {
272	        break;
273	      }
274	    }
275	
276	    if (fused_axis != nullptr) {
277	      Expr fused_exe_time = af::sym::Max(af::sym::kSymbolOne, af::sym::Div(exe_time, *fused_axis));
278	      return HandleBroadcastSplit(node, exe_time, fused_exe_time);
279	    }
280	
281	    if (b_split) {
282	      return HandleReduceOrNormalSplit(node, exe_time, axis, r_split, a_split);
283	    }
284	  }
285	  return TernaryOp(exe_time);
286	}
287	}  // namespace att
