230	  }
231	};
232	
233	struct RuntimeReorderRule {
234	  Expr condition_axis;
235	  Expr compare_axis;
236	  uint32_t condition_threshold{0U};
237	  uint32_t compare_threshold{0U};
238	  std::vector<Expr> preferred_order;
239	};
240	
241	class TilingScheduleConfigTable {
242	 public:
243	  virtual ~TilingScheduleConfigTable() = default;
244	  [[nodiscard]] virtual bool IsEnableBlockLoopAutoTune() const = 0;
245	  [[nodiscard]] virtual bool IsEnableCacheLineCheck() const = 0;
246	  [[nodiscard]] virtual TradeOffConfig GetTradeOffConfig() const = 0;
247	  [[nodiscard]] virtual TilingScheduleConfigPriority GetConfigPriority() const {
248	    return TilingScheduleConfigPriority::kDefaultPriority;
249	  }
250	  // ub利用率大于该值时，性能公式在模板选择是才会生效
251	  [[nodiscard]] virtual double GetUbThresholdPerfValEffect() const = 0;
252	  // 模板比较时，相差超过该值时，才会使用性能公式进行比较，否则直接比较ub利用率
253	  [[nodiscard]] virtual double GetPerfEffectVal() const {
254	    constexpr double kDefaultPerfEffectVal = 5000.0;
255	    return kDefaultPerfEffectVal;
256	  }
257	
258	  // 新增：获取 Model 级别的 Tiling 调度配置
259	  [[nodiscard]] virtual TilingScheduleConfig GetModelTilingScheduleConfig() const = 0;
260	
261	  // 新增：获取 CacheLine 大小
262	  [[nodiscard]] virtual uint32_t GetCacheLineSize() const = 0;
263	
264	  // 新增：获取 Vector length 大小
265	  [[nodiscard]] virtual uint32_t GetVectorLenSize() const {
266	    return arch_param::kDefaultVectorLenSize;
267	  }
268	
269	  // 新增：是否启用Reduce分核Store地址冲突惩罚功能
270	  [[nodiscard]] virtual bool IsCoreNumThresholdPenaltyEnable() const = 0;
271	};
272	
273	struct TilingCaseIdent {
274	  ScheduleGroupIdent schedule_group_ident;
275	  uint32_t tiling_case_id;
276	  std::string sub_case_tag;
277	};
278	
279	struct ModelInfo {
280	  uint32_t tiling_case_id;
281	  std::string graph_name;
282	  std::string score_func;
283	  std::string sub_case_tag;                    // Reduce切R，优先切R轴的模板
284	  std::map<int64_t, Expr> workspace_size_map;  // 用于描述每个tensor_id的workspace大小
285	  std::map<HardwareDef, Expr> hardware_cons;   // 用于描述硬件约束
286	  Expr reserved_ub_size{CreateExpr(0)};
287	  std::map<std::string, std::vector<std::pair<Expr, Expr>>>
288	      eq_exprs;  // 用于描述等式约束,切分轴之间的整除约束key值为NO_TAIL
289	  std::map<std::string, std::vector<Expr>> leq_exprs;              // 用于描述不等式约束
290	  std::map<std::string, NodeApiTilingCode> node_name_to_api_code;  // 用于定义高阶API的代码
291	  std::map<std::string, std::pair<std::string, std::string>>
292	      tiling_api_name_to_vars;       // 工具场景高阶API使用, API名,高阶API变量名,高阶API变量类型
293	  std::map<PipeType, Expr> objects;  // 用于描述目标表达式
294	  std::vector<AttAxisPtr> arg_list;  // 用于描述轴以及轴size的信息, owner att axis ptr
295	  std::map<std::string, Expr> container_exprs;
296	  std::map<std::string, Expr> tensor_exprs;
297	  Expr head_cost{CreateExpr(0)};                           // 用于描述多核头开销
