301	  std::map<Expr, std::string, ExprCmp> variable_name_map;  // 用于记录tensor的名称
302	  std::map<Expr, TernaryOp, ExprCmp> ternary_op_map;       // 用于记录三目运算符的名称
303	  std::vector<PerfBreakdownGroup> perf_breakdowns;         // 用于记录性能公式的语义化拆解
304	  uint32_t output_size;
305	  std::vector<af::AscNodePtr> input_nodes;    // 获取输入schedule_results[0].input_nodes
