307	  bool enable_group_parallel{false};          // 使能group并行
308	  std::vector<Expr> sizes{};                  // 图原始Sizes信息
309	  vector<CacheLineConfig> cache_line_config;  // ub->gm/gm->ub节点的cache配置信息
310	  const TilingScheduleConfigTable *tiling_schedule_config_table{nullptr};
311	  TilingScheduleConfig tiling_schedule_config;            // Model 级别的 Tiling 调度配置
312	  bool is_enable_equal_order_tiling{false};               // 使能等order tiling算法
313	  std::vector<RuntimeReorderRule> runtime_reorder_rules;  // 运行时按shape调整单模板内轴优先级
314	};
315	
316	using TilingModelInfo = std::vector<ModelInfo>;
317	using GroupsTilingModelInfo = std::map<size_t, TilingModelInfo>;
318	using TensorIdSet = std::map<size_t, std::map<size_t, std::set<int64_t>>>;
319	// score_funcs: {level, {asc_graph_id, {impl_graph_id, score_func}}
320	using ScoreFuncs = std::map<kModelInfoLevel, std::map<size_t, std::map<size_t, std::string>>>;
321	using EnableGroupParallels = std::map<size_t, std::map<size_t, bool>>;
322	using VarRelations =
323	    std::map<size_t, std::map<size_t, std::map<size_t, std::map<size_t, std::map<std::string, af::Expression>>>>>;
324	// schedule result id->{score_func, group_model_infos}
