102	std::set<std::string> GetUbContainerNames(const ModelInfo &model_info) {
103	  std::set<std::string> names;
104	  const auto ub_iter = model_info.hardware_cons.find(HardwareDef::UB);
105	  if (ub_iter == model_info.hardware_cons.cend()) {
106	    return names;
107	  }
108	  for (const auto &symbol : ub_iter->second.FreeSymbols()) {
109	    const auto name_iter = model_info.variable_name_map.find(symbol);
110	    const auto name = name_iter == model_info.variable_name_map.cend() ? Str(symbol) : name_iter->second;
111	    if (model_info.container_exprs.find(name) != model_info.container_exprs.cend()) {
112	      names.insert(name);
113	    }
114	  }
115	  return names;
116	}
