234	void to_json(nlohmann::json &j, const SymInfoPtr &arg) {
235	  GE_CHECK_NOTNULL_JUST_RETURN(arg);
236	  auto type = 0U;
237	  uint32_t const_value = 0U;
238	  auto const_arg = std::dynamic_pointer_cast<SymConstInfo>(arg);
239	  if (const_arg != nullptr) {
240	    type = kConstType;
241	    const_value = const_arg->const_value;
242	  }
243	
244	  Expr align = af::Symbol(kDefaultAlignValue);
245	  std::vector<HardwareDef> related_scope;
246	  Expr max_value = af::sym::kSymbolZero;
247	  auto var_arg = std::dynamic_pointer_cast<SymVarInfo>(arg);
248	  std::pair<int64_t, int64_t> value_range;
249	  std::string symbol_expr;
250	  if (var_arg != nullptr) {
251	    type = kVarType;
252	    max_value = var_arg->max_value;
253	    related_scope = var_arg->related_scope;
254	    align = var_arg->align;
255	    value_range = var_arg->value_range;
256	    symbol_expr = (!IsValid(arg->symbol_expr)) ? "" : Str(arg->symbol_expr);
257	  }
258	  const std::string max_value_str = (!IsValid(max_value)) ? "null" : Str(max_value);
259	  j = nlohmann::json{
260	      {"type", (type == kConstType) ? "const" : "var"},
261	      {"symbol_expr", symbol_expr},
262	      {"const_value", const_value},
263	      {"expr_max_value", max_value_str},
264	      {"related_scope", related_scope},
265	      {"align", align},
266	      {"min_value", value_range.first},
267	      {"max_value", value_range.second},
268	  };
269	}
