345	void DumpModelInfo(const std::vector<ModelInfo> &model_info_list, std::string dump_dir = "") {
346	  nlohmann::json j = nlohmann::json{
347	      {"model_info", model_info_list},
348	  };
349	  std::ofstream file_stream;
350	  std::string model_file = kModelInfoFileName;
351	  std::string output_path = dump_dir;
352	  if (output_path.empty()) {
353	    output_path = kModelInfoFilePath;
354	  }
355	  model_file = GetRealPath(output_path) + model_file;
356	  ge::char_t realpath_file[PATH_MAX] = {0x00};
357	  auto ret = realpath(model_file.c_str(), realpath_file);
358	  if (ret == nullptr) {
359	    GELOGD("Model file path [%s] unfound.", model_file.c_str());
360	    return;
361	  }
362	  file_stream.open(realpath_file, std::ios::out | std::ios::trunc);
363	  if (file_stream.is_open()) {
364	    file_stream << j.dump();
365	    file_stream.close();
366	  }
367	}
