407	af::Status GenerateModelInfo(const std::vector<af::AscGraph> &graph_list, std::vector<ModelInfo> &model_info_list,
408	                             const std::map<std::string, std::string> &options, bool enable_group_parallel,
409	                             bool enable_gather_reduce_penalty) {
410	  GE_ASSERT_SUCCESS(CheckKeyValid(graph_list));
411	  uint32_t tiling_key = 0U;
412	  for (auto &graph : graph_list) {
413	    tiling_key = graph.GetTilingKey() >= 0 ? graph.GetTilingKey() : tiling_key;
414	    ModelInfo model_info;
415	    model_info.graph_name = graph.GetName();
416	    model_info.tiling_case_id = tiling_key;
417	    model_info.enable_group_parallel = enable_group_parallel;
418	    std::vector<AttAxisPtr> tiling_R_arg_list;
419	    TuningSpacePtr tuning_space = af::MakeShared<TuningSpace>();
420	    GE_ASSERT_NOTNULL(tuning_space, "Make tuning space failed.");
421	    if (enable_gather_reduce_penalty) {
422	      tuning_space->penalty_cache_line_size = kGatherReducePenaltyCacheLineSize;
423	    }
424	    GELOGD("[DFX] GatherReducePenalty config: graph=%s, enabled=%d, penalty_cache_line_size=%u",
425	           graph.GetName().c_str(), enable_gather_reduce_penalty, tuning_space->penalty_cache_line_size);
426	    tuning_space->cache_line_config = &model_info.cache_line_config;
427	    GetThreadLocalContext().SetOption(options);
428	    GE_ASSERT_SUCCESS(GenerateModelInfo(graph, model_info, tuning_space, tiling_key), "General model info failed.");
429	    if (IsAxesReorderAlgorithm()) {
430	      ArgListReorder arg_list_reorder(tuning_space);
431	      GE_ASSERT_SUCCESS(
432	          arg_list_reorder.SortArgList(model_info.arg_list, tiling_R_arg_list, &model_info.runtime_reorder_rules),
433	          "Sort arg list failed.");
434	    }
435	    const auto iter = options.find(kTilingDataTypeName);
436	    const std::string tiling_data_type = (iter != options.cend()) ? iter->second : "";
437	    ApiTilingParams params{graph, tiling_data_type};
438	    GE_ASSERT_SUCCESS(GetApiTilingInfo(model_info.tiling_case_id, params, model_info.node_name_to_api_code),
439	                      "Generate api tiling info failed.");
440	    // 获取所有的原始size_var
441	    ProcessGraphOriginalSizeVar(graph, model_info);
442	    ProcessTilingR(model_info_list, model_info, tiling_R_arg_list);
443	    model_info_list.emplace_back(model_info);
444	    tiling_key++;
445	  }
446	  GE_ASSERT_TRUE(!model_info_list.empty(), "No graph need convert.");
447	  if (options.find(kDumpDebugInfo) != options.end()) {
448	    DumpModelInfo(model_info_list, options.at(kDumpDebugInfo).back() == '/' ? options.at(kDumpDebugInfo)
449	                                                                            : options.at(kDumpDebugInfo) + "/");
450	  }
451	  return af::SUCCESS;
452	}
