468	af::Status GetAllSubImplGraphs(const ascir::FusedScheduledResult &schedule_results,
469	                               std::vector<std::vector<std::vector<std::vector<af::AscGraph>>>> &all_graphs,
470	                               std::map<std::string, std::string> &all_graph_score_funcs) {
