504	        "%zu, graph name %s.",
505	        asc_graph_id, impl_graph_id, schedule_group_id, schedule_groups[schedule_group_id].size(),
506	        !schedule_groups[schedule_group_id].empty() ? schedule_groups[schedule_group_id][0].GetName().c_str() : "null");
507	    const bool enable_gather_reduce_penalty =
508	        ShouldEnableGatherReducePenalty(schedule_groups, schedule_group_id, out_schedule_groups.enable_group_parallel);
509	    GELOGD(
510	        "[DFX] GatherReducePenalty context: asc_graph_id=%zu, impl_graph_id=%zu, group_id=%zu, group_count=%zu, "
511	        "enabled=%d",
512	        asc_graph_id, impl_graph_id, schedule_group_id, schedule_groups.size(), enable_gather_reduce_penalty);
513	    GE_ASSERT_SUCCESS(GenerateModelInfo(schedule_groups[schedule_group_id], model_info_list, options,
514	                                        out_schedule_groups.enable_group_parallel, enable_gather_reduce_penalty),
515	                      "Get model info failed, impl graph id = %ld, group id = %ld.", impl_graph_id, schedule_group_id);
516	    for (auto &model_info : model_info_list) {
517	      model_info.schedule_group_ident.asc_graph_id = asc_graph_id;
518	      model_info.schedule_group_ident.impl_graph_id = impl_graph_id;
519	      model_info.schedule_group_ident.group_id = schedule_group_id;
520	      model_info.input_nodes = schedule_results.input_nodes;
521	      model_info.output_nodes = schedule_results.output_nodes;
522	      auto it = all_graph_score_funcs.find(model_info.graph_name);
523	      if (it != all_graph_score_funcs.end()) {
524	        model_info.score_func = it->second;
525	      }
526	    }
527	    const auto &ident = model_info_list[0].schedule_group_ident;
528	    GELOGI(
529	        "[DFX]End to gen model info for %s tiling_case size %zu, graph name %s.", ident.GetItemPrefix().c_str(),
530	        schedule_groups[schedule_group_id].size(),
531	        !schedule_groups[schedule_group_id].empty() ? schedule_groups[schedule_group_id][0].GetName().c_str() : "null");
532	    GE_ASSERT_SUCCESS(ReuseGroupUtils::InitReuseScheduleGroup(ident, model_info_list),
533	                      "Init reuse schedule group failed, impl_graph_id[%zu], group_ident[%s].", impl_graph_id,
534	                      ident.GetItemPrefix().c_str());
535	  }
536	  return af::SUCCESS;
537	}
538	}  // namespace
539	
540	af::Status GetModelInfoMap(const ascir::FusedScheduledResult &schedule_results,
541	                           const std::map<std::string, std::string> &options,
542	                           FusedParsedScheduleResult &out_all_model_infos) {
543	  std::vector<std::vector<std::vector<std::vector<af::AscGraph>>>> all_graphs_lists;
544	  std::map<std::string, std::string> all_graph_score_funcs;
545	  GE_ASSERT_SUCCESS(GetAllSubImplGraphs(schedule_results, all_graphs_lists, all_graph_score_funcs));
546	  // 最外层表示asc_graph_id
547	  for (size_t asc_graph_id = 0UL; asc_graph_id < all_graphs_lists.size(); asc_graph_id++) {
548	    auto &out_asc_graph_model_infos = out_all_model_infos[asc_graph_id];
549	    auto &asc_graph_list = all_graphs_lists[asc_graph_id];
550	    // 第二层表示impl_graph_id
551	    for (size_t impl_graph_id = 0UL; impl_graph_id < asc_graph_list.size(); impl_graph_id++) {
552	      if (asc_graph_list[impl_graph_id].empty() || asc_graph_list[impl_graph_id][0].empty()) {
553	        continue;
554	      }
555	      auto &schedule_groups = asc_graph_list[impl_graph_id];
556	      auto &out_schedule_groups = out_asc_graph_model_infos[impl_graph_id];
557	      const auto &schedule_result = schedule_results.node_idx_to_scheduled_results[asc_graph_id][impl_graph_id];
558	      GELOGD(
559	          "out_schedule_groups input values: score_func=%s, enable_group_parallel=%d, asc_graph_id=%zu, "
560	          "impl_graph_id=%zu",
561	          schedule_result.score_func.GetString(), schedule_result.enable_group_parallel, asc_graph_id, impl_graph_id);
562	      out_schedule_groups.score_func = schedule_result.score_func.GetString();
563	      out_schedule_groups.enable_group_parallel = schedule_result.enable_group_parallel;
564	      out_schedule_groups.asc_graph_id = asc_graph_id;
565	      out_schedule_groups.impl_graph_id = impl_graph_id;
566	      out_schedule_groups.var_relations =
567	          schedule_results.node_idx_to_scheduled_results[asc_graph_id][impl_graph_id].var_relations;
568	      GE_ASSERT_SUCCESS(ProcessAndSetScheduleGroupInfo(schedule_groups, all_graph_score_funcs, schedule_results,
569	                                                       options, out_schedule_groups, asc_graph_id, impl_graph_id));
570	    }
571	  }
572	  // 合并所有可以复用的group
573	  GE_ASSERT_SUCCESS(ReuseGroupUtils::MergeAllReusableGroups(all_graphs_lists, out_all_model_infos));
574	  return af::SUCCESS;
575	}
576	}  // namespace att
