581	inline std::string ReorderVarVal() {
582	  std::string general_solver = "";
583	  general_solver += "    for (uint64_t i = 0; i < rec_num; i++)\n";
584	  general_solver += "    {\n";
585	  general_solver += "        GetTemp(i)->CopyVarVal(GetSolution(i));\n";
586	  general_solver += "    }\n";
587	  general_solver += "\n";
588	  general_solver += "    while ((cnt_num < solution_num_) && (temp_idx < rec_num))\n";
589	  general_solver += "    {\n";
590	  general_solver += "        auto temp = GetTemp(temp_idx);\n";
591	  general_solver += "        if (!has_add && (obj < temp->obj || (IsEqual(obj, temp->obj) && cons < temp->cons))) {\n";
592	  general_solver += "            has_add = true;\n";
593	  general_solver += "            GetSolution(cnt_num++)->CopyVarVal(new_var_);\n";
594	  general_solver += "        } else {\n";
595	  general_solver += "            GetSolution(cnt_num++)->CopyVarVal(temp);\n";
596	  general_solver += "            ++temp_idx;\n";
597	  general_solver += "        }\n";
598	  general_solver += "    }\n";
599	  general_solver += "\n";
600	  general_solver += "    if ((!has_add) && (cnt_num < solution_num_))\n";
601	  general_solver += "    {\n";
602	  general_solver += "        GetSolution(cnt_num++)->CopyVarVal(new_var_);\n";
603	  general_solver += "        has_add = true;\n";
604	  general_solver += "    }\n";
605	  return general_solver;
606	}
