609	  std::string general_solver = "";
610	  general_solver += AddVarValAnotation();
611	  general_solver += "inline bool Result::AddVarVal(uint64_t *vars, double obj, double cons)\n";
612	  general_solver += "{\n";
613	  general_solver += "    uint64_t rec_num = solution_num_;\n";
614	  general_solver += "    if (rec_num > MAX_SOLUTION) {\n";
615	  general_solver += "        OP_LOGW(OP_NAME, \"Too much solutions.\");\n";
616	  general_solver += "        return false;\n";
617	  general_solver += "    }\n";
618	  general_solver += "    uint32_t cnt_num = 0;\n";
619	  general_solver += "    uint32_t temp_idx = 0;\n";
620	  general_solver += "    bool has_add = false;\n";
621	  general_solver += "    solution_num_ = Min(solution_num_ + 1, top_n_);\n";
622	  general_solver += "    new_var_->SetVarVal(obj, cons, vars);\n";
623	  general_solver += "    if (rec_num == 0) {\n";
624	  general_solver += "        GetSolution(0)->CopyVarVal(new_var_);\n";
625	  general_solver += "        return true;\n";
626	  general_solver += "    }\n";
627	  general_solver += ReorderVarVal();
628	  general_solver += "    return cnt_num == solution_num_;\n";
629	  general_solver += "}\n";
630	  general_solver += "\n";
631	  return general_solver;
632	}
