691	inline std::string GenGetDescent() {
692	  std::string general_solver = "";
693	  std::string strs = "";
694	  strs += "函数名:GetDescent\n";
695	  strs += "功能描述:获取“缓存占用函数/不等式约束的罚函数”的下降方向\n";
696	  strs += "输入参数:\n";
697	  strs += "  vars:当前待求解参数的下降方向\n";
698	  strs += "  idx:关于某参数下降方向中,某参数的下标\n";
699	  strs += "  func_info:用于指明计算下降方向的函数(FuncInfo::BUFFER/FuncInfo::LEQ)\n";
700	  general_solver += AddAnotationBlock(strs);
701	  general_solver += "template <typename SpecificCase>\n";
702	  general_solver +=
703	      "inline UpdateDirection GeneralSolver<SpecificCase>::GetDescent(uint64_t *vars, int32_t idx, FuncInfo "
704	      "func_info)\n";
705	  general_solver += "{\n";
706	  general_solver += "    if ((idx < 0) || (idx >= var_info_->var_num)) {\n";
707	  general_solver +=
708	      "        OP_LOGW(OP_NAME, \"idx = %d, var_info_->var_num = %d, idx illegal.\", idx, var_info_->var_num);\n";
709	  general_solver += "        return UpdateDirection::NONE;\n";
710	  general_solver += "    }\n";
711	  general_solver += "    static_cast<SpecificCase*>(this)->UpdateLeqs(vars, -1, cons_info_->weight);\n";
712	  general_solver += "    double cur_val = GetFuncVal(vars, func_info);\n";
713	
714	  general_solver += "    vars[idx] += 1;\n";
715	  general_solver += "    double next_val = GetFuncVal(vars, func_info);\n";
716	  general_solver += "    vars[idx] -= 1;\n";
717	  general_solver += "    if (!IsEqual(cur_val, next_val))\n";
718	  general_solver += "    {\n";
719	  general_solver += "        return (cur_val > next_val) ? UpdateDirection::POSITIVE : UpdateDirection::NEGATIVE;\n";
720	  general_solver += "    }\n";
721	
722	  general_solver += "    if (vars[idx] >= 1)\n";
723	  general_solver += "    {\n";
724	  general_solver += "        vars[idx] -= 1;\n";
725	  general_solver += "        double pre_val = GetFuncVal(vars, func_info);\n";
726	  general_solver += "        vars[idx] += 1;\n";
727	  general_solver += "        if (!IsEqual(cur_val, pre_val))\n";
728	  general_solver += "        {\n";
729	  general_solver += "            return (pre_val > cur_val) ? UpdateDirection::POSITIVE : UpdateDirection::NEGATIVE;\n";
730	  general_solver += "        }\n";
731	  general_solver += "    }\n";
732	  general_solver += "    return UpdateDirection::NONE;\n";
733	  general_solver += "}\n";
734	  general_solver += "\n";
735	  return general_solver;
736	}
