781	inline std::string GenSearchVars() {
782	  std::string general_solver = "";
783	  std::string strs = "";
784	  strs += "函数名:SearchVars\n";
785	  strs += "功能描述:用于判断某组解是否曾被搜索过\n";
786	  general_solver += AddAnotationBlock(strs);
787	  general_solver += "inline bool VisitedNode::SearchVars(uint64_t *vars, bool insert_vars) {\n";
788	  general_solver += "    int32_t cmp;\n";
789	  general_solver += "    uint64_t mid;\n";
790	  general_solver += "    int32_t left = 0;\n";
791	  general_solver += "    int32_t right = rec_num;\n";
792	  general_solver += "    while (left < right) {\n";
793	  general_solver += "        mid = (left + right) >> 1;\n";
794	  general_solver += "        cmp = Cmp(mid, vars);\n";
795	  general_solver += "        if (cmp == 0) {\n";
796	  general_solver += "            return true;\n";
797	  general_solver += "        } else if (cmp > 0) {\n";
798	  general_solver += "            right = mid - 1;\n";
799	  general_solver += "        } else {\n";
800	  general_solver += "            left = mid + 1;\n";
801	  general_solver += "        }\n";
802	  general_solver += "    }\n";
803	  general_solver += "    uint32_t uleft = static_cast<uint32_t>(left);\n";
804	  general_solver += "    if (uleft < rec_num && Cmp(uleft, vars) == 0) {\n";
805	  general_solver += "        return true;\n";
806	  general_solver += "    }\n";
807	  general_solver += "    if (rec_num < cfg_iterations && insert_vars) {\n";
808	  general_solver += "        for (uint32_t i = 0u; i < (rec_num - left) * var_num; ++i) {\n";
809	  general_solver += "            head[(rec_num + 1) * var_num - i - 1] = head[rec_num * var_num - i - 1];\n";
810	  general_solver += "        }\n";
811	  general_solver += "        for (uint32_t i = 0u; i < var_num; i++) {\n";
812	  general_solver += "            head[left * var_num + i] = vars[i];\n";
813	  general_solver += "        }\n";
814	  general_solver += "        ++rec_num;\n";
815	  general_solver += "    }\n";
816	  general_solver += "    return false;\n";
817	  general_solver += "}\n";
818	  general_solver += "\n";
819	  return general_solver;
820	}
