920	inline std::string GenGetCoarseLoc() {
921	  std::string general_solver = "";
922	  std::string strs = "";
923	  strs += "函数名:GetCoarseLoc\n";
924	  strs += "功能描述:\n";
925	  strs += "  定域过程中的变量粗调,大致确定变量的落点信息\n";
926	  strs += "  该函数会沿不等式约束的下降方向进行二分搜索\n";
927	  strs += "  最终会输出一个位于约束边界/可行域边界的候选落点\n";
928	  strs += "输入参数:\n";
929	  strs += "  update_info:变量的更新信息,包括下标(idx),下降方向(update_direction)等指标\n";
930	  strs += "  step:变量的更新步长\n";
931	  strs += "  cur_locality:粗调过程中确定的定域优先级\n";
932	  general_solver += AddAnotationBlock(strs);
933	  general_solver += "template <typename SpecificCase>\n";
934	  general_solver +=
935	      "inline bool GeneralSolver<SpecificCase>::GetCoarseLoc(const UpdateInfo &update_info, uint64_t &step, Locality "
936	      "&cur_locality)\n";
937	  general_solver += "{\n";
938	  general_solver += "    uint64_t update_value;\n";
939	  general_solver += "\n";
940	  general_solver += "    int32_t idx = update_info.idx;\n";
941	  general_solver += "    if ((idx < 0) || (idx >= var_info_->var_num)) {\n";
942	  general_solver +=
943	      "        OP_LOGW(OP_NAME, \"idx = %d, var_info_->var_num = %d, idx illegal.\", idx, var_info_->var_num);\n";
944	  general_solver += "        return false;\n";
945	  general_solver += "    }\n";
946	  general_solver += "    uint64_t thres = update_info.thres;\n";
947	  general_solver += "    UpdateDirection update_direction = update_info.update_direction;\n";
948	  general_solver += "    do\n";
949	  general_solver += "    {\n";
950	  general_solver += "        step = (step == 0) ? 1 : (step << 1);\n";
951	  general_solver +=
952	      "        update_value = Bound(var_info_->upper_bound[idx], var_info_->lower_bound[idx], "
953	      "var_info_->rec_vars[idx], step, update_direction);\n";
954	  general_solver += "        UpdateCurVarVal(update_value, idx);\n";
955	  general_solver += "        cur_locality = GetLocality(idx, update_direction);\n";
956	  general_solver += "        var_info_->cur_vars[idx] = var_info_->rec_vars[idx];\n";
957	  general_solver += "        if (cur_locality <= Locality::CROSSREGION)\n";
958	  general_solver += "        {\n";
959	  general_solver +=
960	      "            step = ((cur_locality == Locality::CROSSREGION) && (step != 1)) ? (step >> 1) : step;\n";
961	  general_solver += "            break;\n";
962	  general_solver += "        }\n";
963	  general_solver += "    } while (step < thres);\n";
964	  general_solver +=
965	      "    update_value = Bound(var_info_->upper_bound[idx], var_info_->lower_bound[idx], var_info_->rec_vars[idx], "
966	      "step, update_direction);\n";
967	  general_solver += "    UpdateCurVarVal(update_value, idx);\n";
968	  general_solver += "    return thres != 0;\n";
969	  general_solver += "}\n";
970	  general_solver += "\n";
971	  return general_solver;
972	}
