974	inline std::string GenGetFineLoc() {
975	  std::string general_solver = "";
976	  std::string strs = "";
977	  strs += "函数名:GetFineLoc\n";
978	  strs += "功能描述:\n";
979	  strs += "  定域过程中的变量精调,细致地确定变量的落点\n";
980	  strs += "  后验知识表明约束边界的解相对更好,因此尝试寻找位于边界的可行解\n";
981	  strs += "  该函数会在粗调所得的大致落点附近搜索,寻找不等式约束的边界点\n";
982	  general_solver += AddAnotationBlock(strs);
983	  general_solver += "template <typename SpecificCase>\n";
984	  general_solver +=
985	      "inline bool GeneralSolver<SpecificCase>::GetFineLoc(const UpdateInfo &update_info, uint64_t &step, Locality "
986	      "&cur_locality)\n";
987	  general_solver += "{\n";
988	  general_solver += "    uint64_t update_value;\n";
989	  general_solver += "    Locality rec_locality;\n";
990	  general_solver += "\n";
991	  general_solver += "    int32_t idx = update_info.idx;\n";
992	  general_solver += "    if ((idx < 0) || (idx >= var_info_->var_num)) {\n";
993	  general_solver +=
994	      "        OP_LOGW(OP_NAME, \"idx = %d, var_info_->var_num = %d, idx illegal.\", idx, var_info_->var_num);\n";
995	  general_solver += "        return false;\n";
996	  general_solver += "    }\n";
997	  general_solver += "    UpdateDirection update_direction = update_info.update_direction;\n";
998	  general_solver += "    if (GetLocality(idx, update_direction) <= Locality::LOCALVALID)\n";
999	  general_solver += "    {\n";
1000	  general_solver += "        while (step > 1)\n";
1001	  general_solver += "        {\n";
1002	  general_solver += "            step >>= 1;\n";
1003	  general_solver += "            update_value = var_info_->cur_vars[idx] - GetValue(update_direction) * step;\n";
1004	  general_solver += "            UpdateCurVarVal(update_value, idx);\n";
1005	  general_solver += "            rec_locality = GetLocality(idx, update_direction);\n";
1006	  general_solver += "            if (rec_locality > Locality::CROSSREGION) {\n";
1007	  general_solver += "                update_value = var_info_->cur_vars[idx] + GetValue(update_direction) * step;\n";
1008	  general_solver += "                UpdateCurVarVal(update_value, idx);\n";
1009	  general_solver += "            }\n";
1010	  general_solver += "        }\n";
1011	  general_solver += "        cur_locality = GetLocality(idx, update_direction);\n";
1012	  general_solver += "    }\n";
1013	  general_solver += "    return true;\n";
1014	  general_solver += "}\n";
1015	  general_solver += "\n";
1016	  return general_solver;
1017	}
