1029	inline std::string GenBinPeerSearch() {
1030	  std::string general_solver = "";
1031	  general_solver += "        left_value = (update_direction == UpdateDirection::POSITIVE) ? (rec_value + 1) : 1;\n";
1032	  general_solver +=
1033	      "        right_value = (update_direction == UpdateDirection::POSITIVE) ? (var_info_->upper_bound[idx]) : "
1034	      "(rec_value - var_info_->lower_bound[idx]);\n";
1035	  general_solver += "        while (left_value < right_value)\n";
1036	  general_solver += "        {\n";
1037	  general_solver += "            mid_value = (left_value + right_value) >> 1;\n";
1038	  general_solver += "            UpdateCurVarVal(mid_value, idx);\n";
1039	  general_solver += "            rec_locality = GetLocality(idx, update_direction);\n";
1040	  general_solver += "            if (rec_locality > Locality::LOCALVALID)\n";
1041	  general_solver += "            {\n";
1042	  general_solver += "                left_value = mid_value + 1;\n";
1043	  general_solver += "            }\n";
1044	  general_solver += "            else\n";
1045	  general_solver += "            {\n";
1046	  general_solver += "                right_value = mid_value;\n";
1047	  general_solver += "            }\n";
