1293	  general_solver += "    Locality best_locality = Locality::REJECT;\n";
1294	  general_solver += "    double init_obj = static_cast<SpecificCase*>(this)->GetSmoothObj(var_info_->cur_vars);\n";
1295	  general_solver += "    for (int32_t idx = 0; idx < var_info_->var_num; idx++)\n";
