1386	  std::string strs = "";
1387	  strs += "函数名:SearchLoc\n";
1388	  strs += "功能描述:\n";
1389	  strs += "  沿着指定的更新方向进行探索,检查是否有机会取到更优的可行解\n";
1390	  strs += "  该函数会探索至多solver_config_.search_length步,若存在更优的可行解则会进行标记\n";
1391	  strs += "输入参数:\n";
1392	  strs += "  update_info:变量的更新信息\n";
1393	  strs += "输出参数:\n";
1394	  strs += "  step:取得更优可行解时的步长\n";
1395	  strs += "  cur_obj:微调后变量的目标函数值\n";
1396	  strs += "  cur_priority:微调后变量的优先级\n";
1397	  general_solver += AddAnotationBlock(strs);
1398	  general_solver += "template <typename SpecificCase>\n";
1399	  general_solver +=
1400	      "inline bool GeneralSolver<SpecificCase>::SearchLoc(const UpdateInfo &update_info, uint64_t &step, double "
1401	      "&cur_obj, TunePriority &cur_priority)\n";
1402	  general_solver += "{\n";
1403	  general_solver += "    TunePriority rec_priority{TunePriority::REFUSE};\n";
1404	  general_solver += "    int32_t idx = update_info.idx;\n";
1405	  general_solver += "    if ((idx < 0) || (idx >= var_info_->var_num)) {\n";
1406	  general_solver +=
1407	      "        OP_LOGW(OP_NAME, \"idx = %d, var_info_->var_num = %d, idx illegal.\", idx, var_info_->var_num);\n";
1408	  general_solver += "        return false;\n";
