1411	  general_solver += "    UpdateDirection update_direction = update_info.update_direction;\n";
1412	  general_solver += "    double init_obj = update_info.init_obj;\n";
1413	  general_solver += "    while (step < Min(thres, solver_config_.search_length))\n";
1414	  general_solver += "    {\n";
1415	  general_solver += "        step++;\n";
1416	  general_solver += "        UpdateCurVarVal(var_info_->rec_vars[idx] + GetValue(update_direction) * step, idx);\n";
1417	  general_solver += "        rec_priority = GetTunePriority(idx, init_obj, cur_obj);\n";
1418	  general_solver += "        if (rec_priority <= cur_priority)\n";
1419	  general_solver += "        {\n";
1420	  general_solver += "            cur_priority = rec_priority;\n";
1421	  general_solver += "            break;\n";
1422	  general_solver += "        }\n";
1423	  general_solver += "    }\n";
1424	  general_solver += "    UpdateCurVarVal(var_info_->rec_vars[idx], idx);\n";
1425	  general_solver += "    return rec_priority == cur_priority;\n";
1426	  general_solver += "}\n";
1427	  general_solver += "\n";
1428	  return general_solver;
