1770	inline std::string GenRun(bool open_dt = false) {
1771	  std::string general_solver;
1772	  general_solver += RunAnotation();
1773	  general_solver += "template <typename SpecificCase>\n";
1774	  general_solver += "inline bool GeneralSolver<SpecificCase>::Run(int32_t &solution_num, uint64_t *solutions)\n";
1775	  general_solver += "{\n";
1776	  general_solver += "    uint64_t iter = 1;\n";
1777	  general_solver += "    has_feasible_ = false;\n";
1778	  general_solver += "    while (iter <= solver_config_.iterations)\n";
1779	  general_solver += "    {\n";
1780	  general_solver += "        Initialize(iter);\n";
1781	  general_solver += "        OP_LOGD(OP_NAME, \"iter : %lu\", iter);\n";
1782	  general_solver += "        static_cast<SpecificCase*>(this)->DisplayVarVal(var_info_->cur_vars);\n";
1783	  general_solver += "        if (!is_feasible_)\n";
1784	  general_solver += "        {\n";
1785	  general_solver += "            if (!LocateRegion())\n";
1786	  general_solver += "            {\n";
1787	  general_solver +=
1788	      "                OP_LOGW(OP_NAME, \"The locating process cannot find more valuable updates, triggering an early "
1789	      "stop.\");\n";
1790	  general_solver += "                break;\n";
1791	  general_solver += "            }\n";
1792	  general_solver += "        }\n";
1793	  general_solver += "        else\n";
1794	  general_solver += "        {\n";
1795	  if (open_dt) {
1796	    general_solver += GenDTStrategy();
1797	  } else {
1798	    general_solver += "            if (visited_node_->SearchVars(var_info_->cur_vars, true))\n";
1799	    general_solver += "            {\n";
1800	    general_solver +=
1801	        "                OP_LOGW(OP_NAME, \"Searched a feasible solution again, triggering an early stop.\");\n";
1802	    general_solver += "                break;\n";
1803	    general_solver += "            }\n";
1804	    general_solver += "            if (!FineTune())\n";
1805	    general_solver += "            {\n";
1806	    general_solver += "                break;\n";
1807	    general_solver += "            }\n";
1808	  }
1809	  general_solver += "        }\n";
1810	  general_solver += "        iter++;\n";
1811	  general_solver += "    }\n";
1812	  general_solver += "    result_->GetResult(solution_num, solutions);\n";
1813	  general_solver += "    return solution_num > 0;\n";
1814	  general_solver += "}\n";
1815	  general_solver += "\n";
1816	  return general_solver;
1817	}
1818	
1819	inline std::string GenGetVarNum() {
1820	  std::string general_solver = "";
1821	  general_solver += "template <typename SpecificCase>\n";
1822	  general_solver += "inline int32_t GeneralSolver<SpecificCase>::GetVarNum() const\n";
1823	  general_solver += "{\n";
1824	  general_solver += "    return var_info_->var_num;\n";
1825	  general_solver += "}\n";
1826	  return general_solver;
1827	}
1828	
1829	inline std::string GetGeneralSolver(bool open_dt = false) {
1830	  std::string general_solver = "";
1831	  general_solver += GenConstVars();
1832	  general_solver += GenDef();
1833	  general_solver += GenToolFunc();
1834	  general_solver += GenResultFunc();
1835	  general_solver += GenGetFuncVal();
1836	  general_solver += GenGetDescent();
1837	  general_solver += GenInit();
1838	  general_solver += GenUpdateCurVarVal();
1839	  general_solver += GenCmp();
1840	  general_solver += GenSearchVars();
1841	  general_solver += GenCheckValid();
1842	  general_solver += GenResetMomentum();
1843	  general_solver += GenInitialize();
1844	  general_solver += GetLocateRegion();
1845	  general_solver += GetFineTune();
1846	  general_solver += GenRecordBestVarVal();
1847	  general_solver += GenRun(open_dt);
1848	  general_solver += GenGetVarNum();
1849	  return general_solver;
1850	}
1851	
1852	inline const std::string GENERAL_SOLVER_CODE = GetGeneralSolver(false);
1853	inline const std::string GENERAL_SOLVER_CODE_DT = GetGeneralSolver(true);
1854	}  // namespace att
1855	#endif
