52	// 辅助函数：处理 ternary_ops，生成变量名并更新
53	static void ProcessTernaryOps(const NodeExprId &node_expr_id, const std::string &annotation,
54	                              const PerfOutputInfo &perf_res, std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
55	                              std::vector<Expr> &update_vars, std::vector<std::pair<Expr, Expr>> &replace_vars) {
56	  std::string expr_prefix = node_expr_id.GetExprVarPrefix();
57	  std::string full_desc = node_expr_id.GetVarPrefix();
58	  Expr cur_expr;
59	  for (const auto &pair : perf_res.ternary_ops) {
60	    std::string var_name = expr_prefix + "_" + Str(pair.first) + annotation;
61	    std::string desc = full_desc + "_" + Str(pair.first) + annotation;
62	    GetPerfVar(var_name, cur_expr, ternary_ops);
63	    ternary_ops[cur_expr] = pair.second;
64	    ternary_ops[cur_expr].SetVariable(cur_expr);
65	    ternary_ops[cur_expr].SetDescription(desc);
66	    update_vars.emplace_back(cur_expr);
67	    replace_vars.emplace_back(std::make_pair(pair.first, cur_expr));
68	  }
69	}
