82	// 辅助函数：处理 pipe_res，生成各pipe类型的性能变量
83	static void ProcessPipeRes(const NodeExprId &node_expr_id, const std::string &annotation,
84	                           const PerfOutputInfo &perf_res, std::map<PipeType, Expr> &node_perf,
85	                           std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
86	                           const std::vector<std::pair<Expr, Expr>> &replace_vars) {
87	  std::string expr_prefix = node_expr_id.GetExprVarPrefix();
88	  std::string full_desc = node_expr_id.GetVarPrefix();
89	  Expr perf_expr;
90	  for (const auto &pair : perf_res.pipe_res) {
91	    auto it = PipeType2Str.find(pair.first);
92	    if (it == PipeType2Str.end()) {
93	      continue;
94	    }
95	    std::string var_name = expr_prefix + annotation + "_" + it->second + "_perf";
96	    std::string desc = full_desc + annotation + "_" + it->second + "_perf";
97	    GetPerfVar(var_name, perf_expr, ternary_ops);
98	    auto iter = perf_res.ternary_ops.find(pair.second);
99	    if (iter != perf_res.ternary_ops.end()) {
100	      // 复制 TernaryOp，但需要保留变量、替换和描述设置
101	      ternary_ops[perf_expr] = iter->second;
102	    } else {
103	      ternary_ops[perf_expr] = TernaryOp(pair.second);
104	    }
105	    // 使用传入的 replace_vars 进行变量替换
106	    node_perf[pair.first] = pair.second.Replace(replace_vars);
107	    ternary_ops[perf_expr].Replace(replace_vars);
108	    ternary_ops[perf_expr].UpdateRelatedVars(replace_vars);
109	    ternary_ops[perf_expr].SetVariable(perf_expr);
110	    // 必须在所有操作之后设置描述，因为 Replace/SetVariable/UpdateRelatedVars 可能影响 ternary_ops
111	    ternary_ops[perf_expr].SetDescription(desc);
112	  }
113	}
