115	static void ProcessPerfBreakdowns(const NodeExprId &node_expr_id, const std::string &annotation,
116	                                  const PerfOutputInfo &perf_res,
117	                                  const std::vector<std::pair<Expr, Expr>> &replace_vars,
118	                                  std::vector<PerfBreakdownGroup> &perf_breakdowns) {
119	  if (perf_res.perf_breakdowns.empty()) {
120	    return;
121	  }
122	  const std::string full_desc = node_expr_id.GetVarPrefix();
123	  for (const auto &group : perf_res.perf_breakdowns) {
124	    PerfBreakdownGroup new_group;
125	    new_group.title = full_desc + annotation + " " + group.title;
126	    for (const auto &item : group.items) {
127	      PerfBreakdownItem new_item = item;
128	      new_item.name = full_desc + annotation + "_" + item.name;
129	      new_item.expr = item.expr.Replace(replace_vars);
130	      new_group.items.emplace_back(std::move(new_item));
131	    }
132	    perf_breakdowns.emplace_back(std::move(new_group));
133	  }
134	}
