137	af::Status UpdatePerfRes(const NodeInfo &node, const PerfOutputInfo &perf_res, std::map<PipeType, Expr> &node_perf,
138	                         std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
139	                         std::vector<PerfBreakdownGroup> &perf_breakdowns, bool tail_shape = false) {
140	  NodeExprId node_expr_id = BuildNodeExprId(node);
141	  std::string annotation = tail_shape ? "_tail" : "";
142	  std::vector<Expr> update_vars;
143	  std::vector<std::pair<Expr, Expr>> replace_vars;
144	
145	  GELOGI("Processing performance formula for node type %s, expr prefix: %s, full desc: %s", node.node_type.c_str(),
146	         node_expr_id.GetExprVarPrefix().c_str(), node_expr_id.GetVarPrefix().c_str());
147	
148	  ProcessTernaryOps(node_expr_id, annotation, perf_res, ternary_ops, update_vars, replace_vars);
