156	af::Status CheckOuterAxis(const SubAxis *cut_axis, const std::vector<SubAxis *> from_axes, bool &outer_inside_loop,
157	                          Expr &outer_axis, const int32_t recursive_num = 0) {
158	  GE_ASSERT_TRUE(recursive_num < kMaxRecursiveNum, "CheckOuterAxis failed, recursive_num = %d should < %d",
159	                 kMaxRecursiveNum);
160	  for (const auto &axis : from_axes) {
161	    if (axis->axis_type == AxisPosition::ORIGIN || axis->axis_type == AxisPosition::POSERR) {
162	      continue;
163	    } else if (axis->axis_type == AxisPosition::OUTER) {
164	      GE_ASSERT_TRUE(axis->parent_axis.size() == 1);
165	      if (cut_axis->parent_axis[0] == axis->parent_axis[0]) {
166	        GELOGD("Found outer axis of vectorized axis [%s] in [%s].",
167	               af::SymbolicUtils::ToString(cut_axis->repeat).c_str(),
168	               af::SymbolicUtils::ToString(axis->repeat).c_str());
169	        outer_inside_loop = true;
170	        outer_axis = axis->repeat;
171	        break;
172	      }
173	    } else {
174	      GELOGD("Check outer axis from [%s] (in [%zu] axes).", axis->name.c_str(), axis->parent_axis.size());
175	      GE_ASSERT_SUCCESS(CheckOuterAxis(cut_axis, axis->parent_axis, outer_inside_loop, outer_axis, recursive_num + 1));
176	      if (outer_inside_loop) {
177	        break;
178	      }
179	    }
180	  }
181	  return af::SUCCESS;
182	}
