184	Expr GetTailSize(const Expr &a, const Expr &b, std::map<Expr, TernaryOp, ExprCmp> &ternary_ops) {
185	  Expr tail_size;
186	  if (a.IsConstExpr() && b.IsConstExpr()) {
187	    int32_t a_value;
188	    int32_t b_value;
189	    a.GetConstValue(a_value);
190	    b.GetConstValue(b_value);
191	    if (a_value % b_value == 0) {
192	      tail_size = b;
193	    } else {
194	      tail_size = CreateExpr(a_value % b_value);
195	    }
196	  } else {
197	    tail_size = CreateExpr((Str(b) + "_tail").c_str());
198	    Expr status = af::sym::Mod(a, b);
199	    TernaryOp ternary_op = TernaryOp(CondType::K_EQ, status, CreateExpr(0), b, status);
200	    ternary_op.SetVariable(tail_size);
201	    ternary_ops[tail_size] = ternary_op;
202	    GELOGD("The value of [%s] is [%s]", Str(tail_size).c_str(), ternary_op.GetTernaryOpStr().c_str());
203	  }
204	  return tail_size;
205	}
