307	af::Status PipePerfExpr::GetTensorShapes(const NodeInfo &node, std::vector<TensorShapeInfo> &input_dims,
308	                                         std::vector<TensorShapeInfo> &output_dims,
309	                                         std::map<Expr, TernaryOp, ExprCmp> &ternary_ops, bool tail_shape) const {
