331	af::Status PipePerfExpr::ConvertToPerfInfo(const std::vector<NodeInfo> &node_infos,
332	                                           std::vector<NodePerfInfo> &node_perf_infos,
333	                                           const std::vector<Expr> &vector_func_dims) const {
334	  std::map<Expr, TernaryOp, ExprCmp> ternary_ops;  // 当前暂不使用
335	  for (const auto &sub_node_info : node_infos) {
336	    std::vector<TensorShapeInfo> inputs;
337	    std::vector<TensorShapeInfo> outputs;
338	    NodePerfInfo node_perf;
339	    node_perf.optype = sub_node_info.node_type;
340	    if (!sub_node_info.inputs.empty()) {
341	      node_perf.input_dtype = sub_node_info.inputs[0]->data_type;
342	    }
343	    if (!sub_node_info.outputs.empty()) {
344	      node_perf.output_dtype = sub_node_info.outputs[0]->data_type;
345	      GE_ASSERT_SUCCESS(GetTensorShapes(sub_node_info, inputs, outputs, ternary_ops),
346	                        "Get tensor shape failed, node[%s].", sub_node_info.name.c_str());
347	      GE_ASSERT_TRUE(!outputs.empty(), "Get empty output shape, node[%s].", sub_node_info.name.c_str());
348	      node_perf.dims = outputs[0].dims;
349	      if (!vector_func_dims.empty()) {
350	        // VF子图轴名不会生成外层tiling变量，性能公式使用父VectorFunc实际维度。
351	        node_perf.dims = vector_func_dims;
352	      }
353	    }
354	    GELOGI("[VF_PERF_DFX] convert vf sub node [%s][%s], input_dtype[%s], output_dtype[%s], dims[%s]",
355	           sub_node_info.name.c_str(), sub_node_info.node_type.c_str(), node_perf.input_dtype.c_str(),
356	           node_perf.output_dtype.c_str(), GetVecString(node_perf.dims).c_str());
357	    node_perf_infos.emplace_back(node_perf);
358	  }
359	  return af::SUCCESS;
360	}
