377	Perf PipePerfExpr::UpdateTilingScheduleConfigTable(const NodeInfo &node, bool tail_shape,
378	                                                   PerfOutputInfo &perf_res) const {
379	  Perf perf_func = nullptr;
380	  const auto api_perf = GetApiPerf(node.node_type);
381	  if (api_perf != nullptr) {
382	    perf_func = api_perf->GetPerfFunc();
383	    perf_res.cache_line_config = tuning_space_->cache_line_config;
384	    if (tuning_space_->tiling_schedule_config_table == nullptr ||
385	        (api_perf->GetTilingScheduleConfigTable() != nullptr &&
386	         api_perf->GetTilingScheduleConfigTable()->GetConfigPriority() >
387	             tuning_space_->tiling_schedule_config_table->GetConfigPriority())) {
388	      GELOGD(
389	          "Replace node [%s] type [%s] tiling schedule config table with api perf tiling schedule config table, "
390	          "is_enable = %d, core_num_ratio = %s, ub_ratio = %s.",
391	          node.name.c_str(), node.node_type.c_str(),
392	          api_perf->GetTilingScheduleConfigTable()->GetTradeOffConfig().is_enable,
393	          Str(api_perf->GetTilingScheduleConfigTable()->GetTradeOffConfig().core_num_ratio).c_str(),
394	          Str(api_perf->GetTilingScheduleConfigTable()->GetTradeOffConfig().ub_ratio).c_str());
395	      tuning_space_->tiling_schedule_config_table = api_perf->GetTilingScheduleConfigTable();
396	    }
397	  }
398	  // tail_shape场景：仅整块需要进行cache line检查，尾块大小一定是小于整块的，不需要进行cache line大小检查
399	  if (tail_shape || tuning_space_->tiling_schedule_config_table == nullptr ||
400	      !tuning_space_->tiling_schedule_config_table->IsEnableCacheLineCheck()) {
401	    perf_res.cache_line_config = nullptr;
402	  }
403	  return perf_func;
404	}
