406	af::Status PipePerfExpr::GetNodePerf(const NodeInfo &node, std::map<PipeType, Expr> &node_perf,
407	                                     std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
408	                                     std::vector<PerfBreakdownGroup> &perf_breakdowns, bool tail_shape) const {
409	  std::string tail_annotation;
410	  if (tail_shape) {
411	    tail_annotation = "tail ";
412	  }
413	  const auto &node_type = node.node_type;
414	  const auto &node_unit = node.node_unit;
415	  std::vector<TensorShapeInfo> inputs;
416	  std::vector<TensorShapeInfo> outputs;
417	  GE_ASSERT_SUCCESS(GetTensorShapes(node, inputs, outputs, ternary_ops, tail_shape), "Get tensor shape failed!");
418	  for (size_t i = 0; i < inputs.size(); i++) {
419	    GELOGD("node[%s, %s] input[%zu] %sshape: {%s}", node.name.c_str(), node.node_type.c_str(), i,
420	           tail_annotation.c_str(), inputs[i].GetDimExpr().c_str());
421	  }
422	  for (size_t i = 0; i < outputs.size(); i++) {
423	    GELOGD("node[%s, %s] output[%zu] %sshape: {%s}", node.name.c_str(), node.node_type.c_str(), i,
424	           tail_annotation.c_str(), outputs[i].GetDimExpr().c_str());
425	  }
426	  PerfOutputInfo perf_res;
427	  Perf perf_func = UpdateTilingScheduleConfigTable(node, tail_shape, perf_res);
428	  // 获取pipe的兜底性能
429	  if (perf_func == nullptr) {
430	    GELOGD("Get node [%s] type [%s] perf func failed, node_unit = %s.", node.name.c_str(), node_type.c_str(),
431	           node_unit.c_str());
432	    perf_func = EvalCosts::Instance().GetFunc(node_unit);
433	  }
434	  GE_ASSERT_NOTNULL(perf_func, "Get node type [%s] perf func failed, node unit[%s].", node_type.c_str(),
435	                    node_unit.c_str());
436	
437	  if (perf_func(inputs, outputs, node, perf_res) != af::SUCCESS) {
438	    GELOGW("Perf func failed for node[%s, %s], perf_res may be incomplete.", node.name.c_str(), node.node_type.c_str());
439	  }
440	  GELOGD("node[%s, %s] perf res: {%s}", node.name.c_str(), node.node_type.c_str(), perf_res.ToString().c_str());
441	  GE_ASSERT_SUCCESS(UpdatePerfRes(node, perf_res, node_perf, ternary_ops, perf_breakdowns, tail_shape));
442	  return af::SUCCESS;
443	}
