445	af::Status PipePerfExpr::GetNodeExeTime(const NodeInfo &node, const ExeTimePassManager &exe_time_mgr,
446	                                        TernaryOp &cur_exe_time) const {
447	  Expr exe_time = CreateExpr(1U);
448	  for (auto &loop_axis : node.loop_axes) {
449	    exe_time = af::sym::Mul(exe_time, loop_axis->repeat);
450	  }
451	  GE_ASSERT_TRUE(IsValid(exe_time), "Get node exe times expr failed.");
452	  cur_exe_time = exe_time_mgr.UpdateNodeExeTime(node, exe_time);
453	  std::string exe_time_name = att::SanitizeNodeName(node.name) + "_exe_time";
454	  cur_exe_time.SetVariable(CreateExpr(exe_time_name.c_str()));
455	  ArgListManager::GetInstance().SetArgExpr(exe_time_name, cur_exe_time.GetVariable());
456	  return af::SUCCESS;
457	}
