500	af::Status PipePerfExpr::GetTailExeTime(const NodeInfo &node, const Expr &node_exe_times, Expr &tail_exe_times) {
501	  Expr outer_axis;
502	  const SubAxis *cut_axis = nullptr;
503	  bool outer_inside_loop = false;
504	  for (const auto &input : node.inputs) {
505	    for (const auto &dim : input->dim_info) {
506	      if (dim->axis_type == AxisPosition::INNER) {
507	        GE_ASSERT_TRUE(dim->parent_axis.size() == 1);
508	        GE_ASSERT_TRUE(cut_axis == nullptr || cut_axis == dim);
509	        cut_axis = dim;
510	      }
511	    }
512	  }
513	  for (const auto &output : node.outputs) {
514	    for (const auto &dim : output->dim_info) {
515	      if (dim->axis_type == AxisPosition::INNER) {
516	        GE_ASSERT_TRUE(dim->parent_axis.size() == 1);
517	        GE_ASSERT_TRUE(cut_axis == nullptr || cut_axis == dim);
518	        cut_axis = dim;
519	      }
520	    }
521	  }
522	  if (cut_axis != nullptr) {
523	    for (const auto &loop_axis : node.loop_axes) {
524	      GE_ASSERT_SUCCESS(CheckOuterAxis(cut_axis, loop_axis->parent_axis, outer_inside_loop, outer_axis));
525	    }
526	  }
527	  if (outer_inside_loop) {
528	    tail_exe_times = af::sym::Ceiling(node_exe_times / outer_axis);
529	  } else {
530	    tail_exe_times = af::sym::kSymbolOne;
531	  }
532	  GELOGD("Exe Time of tail block is [%s].", af::SymbolicUtils::ToString(tail_exe_times).c_str());
533	  return af::SUCCESS;
534	}
