629	// 添加节点性能到pipe_costs
630	af::Status PipePerfExpr::AddNodePerfToPipeCost(const NodeInfo &node, const Expr &exe_var,
631	                                               const std::map<PipeType, Expr> &node_perf,
632	                                               std::map<PipeType, Expr> &pipe_costs,
633	                                               std::map<Expr, TernaryOp, ExprCmp> &ternary_ops,
634	                                               std::vector<PerfBreakdownGroup> &perf_breakdowns) {
635	  NodeExprId node_expr_id = BuildNodeExprId(node);
636	  std::string expr_prefix = node_expr_id.GetExprVarPrefix();
637	  PerfAddContext ctx(node_perf, pipe_costs, ternary_ops, expr_prefix);
638	  if (CheckSingleCut(node)) {
639	    GELOGD("Node with single cut, add tail perf.");
640	    Expr tail_exe_time;
641	    std::map<PipeType, Expr> node_tail_perf;
642	    GE_ASSERT_SUCCESS(GetNodePerfInternal(node, node_tail_perf, ternary_ops, perf_breakdowns, true),
643	                      "Get node [%s] tail perf failed.", node.name.c_str());
644	    GE_ASSERT_SUCCESS(GetTailExeTime(node, exe_var, tail_exe_time));
645	    GE_ASSERT_SUCCESS(AddTailPerf(tail_exe_time, exe_var, node_tail_perf, ctx));
646	  } else {
647	    GE_ASSERT_SUCCESS(AddPerf(exe_var, "contrib", ctx));
648	  }
649	  return af::SUCCESS;
650	}
